class Solution {
    using ll = long long;

    struct Node {
        int len;
        ll prefix, suffix, noPeak;

        Node(int l = 0, ll p = 0,
             ll s = 0, ll z = 0)
            : len(l), prefix(p), suffix(s), noPeak(z) {}
    };

    vector<Node> tree;
    vector<int> peak;
    int n;

    Node merge(const Node& a, const Node& b) {
        if (a.len == 0) return b;
        if (b.len == 0) return a;

        Node res;
        res.len = a.len + b.len;

        res.prefix = (a.prefix == a.len)
                   ? a.len + b.prefix : a.prefix;

        res.suffix = (b.suffix == b.len)
                   ? b.len + a.suffix : b.suffix;

        res.noPeak = a.noPeak + b.noPeak
                   + a.suffix * b.prefix;

        return res;
    }

    Node leaf(int isPeak) {
        if (isPeak)
            return Node(1, 0, 0, 0);

        return Node(1, 1, 1, 1);
    }

    void build(int node, int l, int r) {
        if (l == r) {
            tree[node] = leaf(peak[l]);
            return;
        }

        int mid = l + (r - l) / 2;

        build(node * 2, l, mid);
        build(node * 2 + 1, mid + 1, r);

        tree[node] = merge(
            tree[node * 2],
            tree[node * 2 + 1]
        );
    }

    void update(int node, int l, int r,
                int index, int value) {
        if (l == r) {
            tree[node] = leaf(value);
            return;
        }

        int mid = l + (r - l) / 2;

        if (index <= mid)
            update(node * 2, l, mid, index, value);
        else
            update(node * 2 + 1, mid + 1, r,
                   index, value);

        tree[node] = merge(
            tree[node * 2],
            tree[node * 2 + 1]
        );
    }

    Node query(int node, int l, int r,
               int ql, int qr) {
        if (qr < l || r < ql)
            return Node();

        if (ql <= l && r <= qr)
            return tree[node];

        int mid = l + (r - l) / 2;

        return merge(
            query(node * 2, l, mid, ql, qr),
            query(node * 2 + 1, mid + 1, r,
                  ql, qr)
        );
    }

public:
    vector<long long> countOfPeaks(
        vector<int>& nums,
        vector<vector<int>>& queries) {

        n = (int)nums.size();

        peak.assign(n, 0);
        tree.resize(4 * n + 5);

        auto isPeak = [&](int i) -> int {
            if (i <= 0 || i >= n - 1)
                return 0;

            return nums[i] > nums[i - 1] &&
                   nums[i] > nums[i + 1];
        };

        for (int i = 1; i < n - 1; ++i)
            peak[i] = isPeak(i);

        build(1, 0, n - 1);

        vector<long long> answer;

        for (const auto& q : queries) {
            if (q[0] == 1) {
                int l = q[1];
                int r = q[2];

                if (r - l + 1 < 3) {
                    answer.push_back(0);
                    continue;
                }

                // Only interior positions can be peaks.
                int left = l + 1;
                int right = r - 1;

                Node result = query(
                    1, 0, n - 1, left, right
                );

                ll len = right - left + 1;

                ll total = len * (len + 1) / 2;

                answer.push_back(
                    total - result.noPeak
                );

            } else {
                int index = q[1];
                int val = q[2];

                nums[index] = val;

                // Only three positions can change.
                for (int i = max(1, index - 1);
                     i <= min(n - 2, index + 1);
                     ++i) {

                    int now = isPeak(i);

                    if (peak[i] != now) {
                        peak[i] = now;
                        update(1, 0, n - 1, i, now);
                    }
                }
            }
        }

        return answer;
    }
};
